syntax = "proto3";
package orderservice.v1;

option go_package = "github.com/example/orderservice/api/v1;v1";

import "google/protobuf/timestamp.proto";
import "google/protobuf/empty.proto";

// 订单服务定义
service OrderService {
  // Unary RPC
  rpc CreateOrder(CreateOrderRequest) returns (Order);
  rpc GetOrder(GetOrderRequest) returns (Order);
  // Server Streaming
  rpc ListOrders(ListOrdersRequest) returns (stream Order);
  // Client Streaming
  rpc BatchCreateOrders(stream CreateOrderRequest) returns (BatchCreateResponse);
  // Bidirectional Streaming
  rpc WatchOrderUpdates(WatchRequest) returns (stream OrderEvent);
}

message Order {
  string id = 1;
  string customer_id = 2;
  repeated OrderItem items = 3;
  OrderStatus status = 4;
  double total_amount = 5;
  google.protobuf.Timestamp created_at = 6;
}

message OrderItem {
  string sku = 1;
  int32 quantity = 2;
  double unit_price = 3;
}

enum OrderStatus {
  ORDER_STATUS_UNSPECIFIED = 0;
  ORDER_STATUS_PENDING = 1;
  ORDER_STATUS_CONFIRMED = 2;
  ORDER_STATUS_SHIPPED = 3;
  ORDER_STATUS_DELIVERED = 4;
  ORDER_STATUS_CANCELLED = 5;
}

message CreateOrderRequest {
  string customer_id = 1;
  repeated OrderItem items = 2;
}

message GetOrderRequest {
  string id = 1;
}

message ListOrdersRequest {
  string customer_id = 1;
  int32 page_size = 2;
  string page_token = 3;
}

message BatchCreateResponse {
  int32 success_count = 1;
  repeated string errors = 2;
}

message WatchRequest {
  string customer_id = 1;
}

message OrderEvent {
  string order_id = 1;
  OrderStatus new_status = 2;
  google.protobuf.Timestamp timestamp = 3;
}
